var i=`0188-focaccia`;var t=`world-0188`;var n=`IT`;var o=`southern-europe`;var r=4;var s=118;var l={en:`Focaccia`,ua:`Фокача`};var u={en:`A classic dish from Italy, featuring rosemary, bread flour, instant yeast, extra virgin olive oil. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: розмарин, хлібне борошно, інстантні дріжджі, оливкова олія екстра вірджин. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`bread-flour`,530,`g`],[`water`,390,`ml`],[`instant-yeast`,6,`g`],[`table-salt`,10,`g`],[`extra-virgin-olive-oil`,50,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 20 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 20 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:20,i:[[`rosemary`,18,`g`],[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 18 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 18 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:18,i:[[`flaky-sea-salt`,6,`g`]]}];var g={slug:i,id:t,country:`IT`,region:o,servings:4,minutes:118,title:l,text:u,steps:d};export{n as country,g as default,t as id,s as minutes,o as region,r as servings,i as slug,d as steps,u as text,l as title};